<dialog id="{{ $dialogId }}" class="purchase-payment-dialog"><div class="modal-heading"><div><span class="eyebrow">{{ $purchase->reference }}</span><h2>{{ $heading }}</h2></div><button type="button" class="icon-button" data-close-purchase-dialog aria-label="Close payment dialog"><x-icon name="x"/></button></div><form class="modal-body" method="POST" action="{{ $action }}">@csrf<input type="hidden" name="token" value="{{ old('payment_action')===$paymentAction?old('token',\Illuminate\Support\Str::uuid()):\Illuminate\Support\Str::uuid() }}"><input type="hidden" name="payment_action" value="{{ $paymentAction }}"><div class="purchase-dialog-balance"><span>{{ $paymentAction==='REFUND'?'Refund available':'Balance due' }}</span><strong>{{ $currency }} {{ \App\Support\Money::display($limit) }}</strong></div><p class="muted mb-4">{{ $note }}</p><label class="field">{{ $paymentAction==='REFUND'?'Amount':'Amount given' }}<input type="number" name="amount" min="0.01" max="{{ $paymentAction==='REFUND'?$limit:'9999999999999.99' }}" data-due="{{ $limit }}" step="0.01" value="{{ old('payment_action')===$paymentAction?old('amount',$limit):$limit }}" required inputmode="decimal"></label><p class="purchase-payment-change" hidden>Change balance: <strong></strong></p><label class="field">Payment method<select name="payment_method_id" required onchange="const take = this.form.querySelector('.take-from-register'); if(take) take.style.display = (this.options[this.selectedIndex].dataset.type === 'CASH') ? 'flex' : 'none';"><option value="">Choose payment method</option>@foreach($methods as $method)<option value="{{ $method->id }}" data-type="{{ $method->type }}" @selected(old('payment_action')===$paymentAction && (string)old('payment_method_id')===(string)$method->id)>{{ $method->name }}</option>@endforeach</select></label><label class="field full take-from-register" style="display:{{ (collect($methods)->firstWhere('id', old('payment_action') === $paymentAction ? old('payment_method_id') : '')?->type === 'CASH') ? 'flex' : 'none' }}; flex-direction:row; align-items:center; gap:0.5rem; margin-top:-0.5rem;"><input type="hidden" name="take_from_register" value="0"><input type="checkbox" name="take_from_register" value="1" @checked(old('payment_action')===$paymentAction ? old('take_from_register', true) : true)><span>Take cash from open register drawer</span></label><label class="field">Reference <small class="muted">optional</small><input name="reference" maxlength="255" value="{{ old('payment_action')===$paymentAction?old('reference'):'' }}" placeholder="Bank or supplier payment reference"></label><div class="form-footer"><button type="button" class="btn secondary" data-close-purchase-dialog>Cancel</button><button class="btn primary"><x-icon name="check"/>{{ $buttonLabel }}</button></div></form></dialog>
